export default(function(el){var details=el.querySelectorAll(".details");var onclick=function onclick(selected){details.forEach(function(detail){var summary=detail.querySelector(".summary");var content=detail.querySelector("#".concat(summary.getAttribute("aria-controls")));var expanded=summary.getAttribute("aria-expanded")==="false"?true:false;summary.setAttribute("aria-expanded",selected===summary?expanded:false);content.setAttribute("aria-hidden",selected===summary?!expanded:true)})};details.forEach(function(detail){var summary=detail.querySelector(".summary");summary.onclick=function(){return onclick(summary)}})});